#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long sumOfGcdPairs(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        long long total = 0;
        for (int i = 0; i < n / 2; ++i) {
            total += std::gcd(nums[i], nums[n - 1 - i]);
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long sumOfGcdPairs(int[] nums) {
        Arrays.sort(nums);
        int n = nums.length;
        long total = 0;
        for (int i = 0; i < n / 2; i++) {
            total += gcd(nums[i], nums[n - 1 - i]);
        }
        return total;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

